public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE (Level__c = 'ERROR' AND CreatedDate < LAST_N_DAYS:180) 
               OR (Level__c != 'ERROR' AND CreatedDate < LAST_N_DAYS:30)
               OR (Level__c = NULL AND CreatedDate < LAST_N_DAYS:30)
            LIMIT 9000
        ];

        if (!logsToDelete.isEmpty()) {
            delete logsToDelete;
            Database.emptyRecycleBin(logsToDelete);
        }
    }

    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }
}
