        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        List<npsp__DataImport__c> diList = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c(
                npsp__Contact1_Firstname__c = gift.firstName,
                npsp__Contact1_Lastname__c = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c = gift.amount,
                npsp__Donation_Date__c = gift.giftDate,
                npsp__Donation_Donor__c = 'Contact1'
            );
            diList.add(di);
        }

        // Insert the Data Import records so they stay in the org as an audit trail
        insert diList;

        // Process the records synchronously using NPSP's Data Import API
        // Use the org's defaults to ensure matching rules are applied correctly
        npsp__Data_Import_Settings__c settings = npsp__Data_Import_Settings__c.getOrgDefaults();
        npsp.BDI_DataImport_API.processDataImportRecords(settings, diList, false);

        // Query the updated records to get the processing results
        Map<Id, npsp__DataImport__c> updatedDiMap = new Map<Id, npsp__DataImport__c>([
            SELECT npsp__Status__c, npsp__Contact1Imported__c, npsp__DonationImported__c, npsp__FailureInformation__c 
            FROM npsp__DataImport__c 
            WHERE Id IN :diList
        ]);

        // Build the results in the input order
        for (npsp__DataImport__c di : diList) {
            npsp__DataImport__c updatedDi = updatedDiMap.get(di.Id);
            ImportResult res = new ImportResult();
            res.success = (updatedDi.npsp__Status__c == 'Imported');
            res.contactId = updatedDi.npsp__Contact1Imported__c;
            res.opportunityId = updatedDi.npsp__DonationImported__c;

            if (!res.success) {
                res.errorMessage = updatedDi.npsp__FailureInformation__c;
            }
            results.add(res);
        }

        return results;
    }
}
